  },
  "npcs": [
    {
      "name": "Йорген",
      "role": "Старый моряк",
      "summary": "Морщинистый старик с пронзительным взглядом, который, кажется, знает все тайны моря и портовых слухов.",
      "voice": "Говорит хриплым, но отчётливым голосом, часто сопровождая рассказы жестами.",
      "goals": [
        "Поделиться историями и получить выпивку."
      ],
      "beliefs": [
        "Море всегда берёт своё.",
        "Молчание — золото, но истории — тоже валюта."
      ]
    },
    {
      "name": "Кайл",
      "role": "Трактирщик",
      "summary": "Молчаливый и наблюдательный хозяин таверны, который, кажется, знает больше, чем говорит.",
      "voice": "Говорит низким, ровным голосом, предпочитая короткие ответы.",
      "goals": [
        "Поддерживать порядок в таверне и получать прибыль."
      ],
      "beliefs": [
        "Информация — это товар.",
        "Клиент всегда прав, пока платит."
      ]
    }
  ],
  "hook": "Исчезновение каравана на северном тракте и связанные с этим долги героев, а также растущие слухи о таинственных событиях на границе."
}
